+            dataStream,
+            dataStreamDescriptor.getDataStreamName(),
+            feature.getName(),
+            dataStreamDescriptor.getOrigin(),
+            feature
+        );
+    }
+
+    public String getDataStreamName() {
+        return dataStreamName;
+    }
+
+    @Override
+    protected String getCurrentResourceName() {
+        return getDataStreamName();
+    }
+
